}

.rbccm-filtered-content--dark .rbccm-filtered-content__page-button:hover,
.rbccm-filtered-content--dark .rbccm-filtered-content__page-button:focus-visible {
  border-color: #FFC72C;
  color: #FFC72C;
}

/* Dark theme arrow hover/focus: fill yellow, dark-blue chevron.
   Mirrors the light-theme "fill circle + invert chevron" treatment
   using the RBC brand yellow accent. */
.rbccm-filtered-content--dark .rbccm-filtered-content__page-button--previous:hover,
.rbccm-filtered-content--dark .rbccm-filtered-content__page-button--next:hover,
.rbccm-filtered-content--dark .rbccm-filtered-content__page-button--previous:focus-visible,
.rbccm-filtered-content--dark .rbccm-filtered-content__page-button--next:focus-visible {
