  border-color: #FFC72C;
}

.rbccm-filtered-content--dark .rbccm-filtered-content__page-button--previous:hover .rbccm-filtered-content__page-button-icon,
.rbccm-filtered-content--dark .rbccm-filtered-content__page-button--next:hover .rbccm-filtered-content__page-button-icon,
.rbccm-filtered-content--dark .rbccm-filtered-content__page-button--previous:focus-visible .rbccm-filtered-content__page-button-icon,
.rbccm-filtered-content--dark .rbccm-filtered-content__page-button--next:focus-visible .rbccm-filtered-content__page-button-icon {
