}

.rbccm-filtered-content--dark .rbccm-filtered-content__search-input::placeholder {
  color: rgba(255, 255, 255, 0.6);
}

.rbccm-filtered-content--dark .rbccm-filtered-content__reset {
  border-color: #FFC72C;
  color: #FFC72C;
}

.rbccm-filtered-content--dark .rbccm-filtered-content__reset:hover,
.rbccm-filtered-content--dark .rbccm-filtered-content__reset:focus-visible {
  background: #FFC72C;
  color: #002144;
}

.rbccm-filtered-content--dark .rbccm-filtered-content__page-button {
  background: transparent;
  border-color: rgba(255, 255, 255, 0.5);
