}


/* Empty-state DARK variant.
   Applied automatically by JS when the parent filter has --dark. */
.rbccm-filtered-content__empty--dark .rbccm-filtered-content__empty-icon-wrapper {
  background: rgba(45, 106, 168, 0.20);
  border-color: #1D86F0;
  color: #FFFDFD;
}

.rbccm-filtered-content__empty--dark .rbccm-filtered-content__empty-heading,
.rbccm-filtered-content__empty--dark .rbccm-filtered-content__empty-message {
