.wheel {
  perspective: 1000px;
  margin: 50px 0;
}
.wheel .wheel__inner {
  position: relative;
  width: 100%;
  height: 350px;
  margin: 0 auto;
  transform-style: preserve-3d;
  animation-iteration-count: infinite;
  animation-timing-function: linear;
  animation-name: spin;
  animation-duration: 27s;
  animation-direction: reverse;
}
.wheel .wheel__inner .wheel__segment {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 40px;
  position: absolute;
  top: 50%;
  color: #fff;
  opacity: 0.4;
  font-size: 15px;
  color: #fff;
  transition: all 0.8s ease-in-out;
}
.wheel .wheel__inner .wheel__segment.active {
  font-size: 18px;
  opacity: 1;
  transition: all 0.8s ease-in-out;
}
.wheel .wheel__inner .wheel__segment.active span {
  border-bottom: 0.5px solid rgba(255, 255, 255, 0.3);
}
.wheel .wheel__inner .wheel__segment.inactive {
  opacity: 0;
}
.wheel .wheel__inner .wheel__segment span {
  border-bottom: 1px solid #fff;
  padding-bottom: 20px;
}
@-webkit-keyframes spin {
  0% {
    transform: rotateX(360deg);
  }
  50% {
    transform: rotateX(180deg);
  }
  100% {
    transform: rotateX(0deg);
  }
}
