  font-family: 'Clarkson', Helvetica, sans-serif;
  font-style: normal;
  font-weight: 500;
  line-height: 1.2em;
  letter-spacing: 0;
  text-rendering: geometricPrecision;
  text-decoration: none;
  font-size: 16px;
