.gray-rollover .rollover {
  padding: 20px;
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  bottom: 0;
  background: linear-gradient(
    90deg,
    rgba(4, 51, 98, 1) 15%,
    rgba(0, 115, 189, 1) 100%
  );
  text-align: center;
  z-index: 10;
  transition: border-radius 350ms ease;
  transform: translate(0, 100%);
  height: 100%;
  transition: transform 0.5s ease;
}

.gray-rollover .rollover * {
  color: #fff;
}

.gray-rollover .fa-chevron-down,
.custom-info-box .fa-chevron-down {
  margin-right: auto;
  margin-left: auto;
  left: 45%;
  position: absolute;
  bottom: 20px;
}

.custom-info-box .fa-chevron-down {
  left: 48%;
  opacity: 0;
}

.gray-rollover:hover .rollover,
.gray-rollover:focus .rollover {
  display: block;
  transition: border-radius 350ms ease;
  display: flex;
  justify-content: center;
  align-content: center;
  flex-direction: column;
  padding-top: 80px;
  transform: translate(0, 0);
  transition: transform 0.5s ease;
  transition-timing-function: cubic-bezier(0, 1, 0.5, 1);
}

