.animated-underline-wrapper {
  position: relative;
  border-bottom: none;
}

.animated-underline {
  white-space: nowrap;
  position: relative;
  border-bottom: none;
  font-family: "Clarkson", Helvetica, sans-serif;
  font-style: normal;
  font-weight: 500;
  line-height: 1.2em;
  letter-spacing: 0;
  text-rendering: geometricPrecision;
  text-decoration: none;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  display: inline-block;
  color: #fff;
}

.animated-underline.dark {
  color: #fff;
}

.animated-underline-text {
  position: relative;
  padding-bottom: 1px;
  background-repeat: no-repeat;
  background-image: -webkit-gradient(
      linear,
      left top,
      left bottom,
      from(currentColor),
      to(currentColor)
    ),
    -webkit-gradient(linear, left top, left bottom, from(currentColor), to(currentColor));
  background-image: linear-gradient(currentColor, currentColor),
    linear-gradient(currentColor, currentColor);
  background-size: 51% 1px, 50% 1px;
  background-position: 0 100%, 100% 100%;
  -webkit-animation: underlineSlideIn 0.5s cubic-bezier(0.694, 0, 0.335, 1)
    forwards;
  animation: underlineSlideIn 0.5s cubic-bezier(0.694, 0, 0.335, 1) forwards;
}

.animated-underline:hover {
  border-bottom: none;
}

.animated-underline-text:hover {
  border-bottom: none;
  -webkit-animation: underlineSlideOut 0.5s cubic-bezier(0.694, 0, 0.335, 1)
    forwards;
  animation: underlineSlideOut 0.5s cubic-bezier(0.694, 0, 0.335, 1) forwards;
}

.parallax {
  position: absolute;
  -webkit-transition: all 500ms ease;
  -moz-transition: all 500ms ease;
  -ms-transition: all 500ms ease;
  -o-transition: all 500ms ease;
  transition: all 500ms ease;
