@media (min-width: 601px) {
  .partners-slide {
    width: 48%;
    padding-bottom: 0;
    position: relative;
  }

  .partners-slide .slide-wrapper {
    min-height: 320px;
    height: 320px;
    padding: 10px;
    padding-left: 30px;
  }

  .slick-slide div > .partners-slide:first-child .slide-wrapper {
    padding-left: 0;
  }

  .slick-slide div > .partners-slide:first-child .slide-wrapper:after {
    content: "";
    height: 98%;
    width: 1px;
    background: #bfcbd9;
    position: absolute;
    top: 0;
    right: 0;
  }

  .slick-slide > div:nth-child(2) .partners-slide .slide-wrapper:before {
    content: "";
    width: 96%;
    height: 1px;
    background: #bfcbd9;
    position: absolute;
    top: 0;
    left: 0;
  }

  .slick-slide
    > div:nth-child(2)
    .partners-slide:nth-child(2)
    .slide-wrapper:before {
    right: 0;
    left: auto;
  }
}

