/* Author attribution — flexbox layout */
.attribution-wrapper {
display: flex;
align-items: center;
flex-direction: row; /* row above 475px */
column-gap: 30px;
row-gap: 15px;
flex-wrap: nowrap;
}

/* Avatar column — fixed 75px */
.attribution-wrapper > div:first-child {
flex: 0 0 75px;
width: 75px;
max-width: 75px;
padding: 0;
}
.attribution-wrapper > div:first-child img {
width: 100%;
height: auto;
}

/* Text column — fills remaining space */
.attribution-wrapper > div:last-child {
flex: 1 1 auto;
min-width: 0;
padding: 0;
}
.attribution-wrapper .attribution {
margin-left: 0;
}

/* Small phones (≤475px): stack avatar on top, centered */
@media (max-width: 475px) {
.attribution-wrapper {
flex-direction: column;
align-items: center;
}
.attribution-wrapper .attribution {
text-align: center;
}
}

