/*Rollover tiles*/

.gray-rollover {
    background-color: #e7eef1;
    padding: 25px 20px;
    color: #0c213d;
    font-size: 18px;
    min-height: 250px;
    margin-bottom: 30px;
    -webkit-box-shadow: -1px 5px 8px 7px rgba(5,0,62,.5);
    box-shadow: -1px 5px 8px 7px rgba(5,0,62,.5);
    overflow: hidden;
    margin-bottom: 50px
}

.gray-rollover .challenge {
    width: 140px;
    text-transform: uppercase;
    border-bottom: 1px solid #0c213d;
    padding-bottom: 10px;
    margin-bottom: 30px
}

.gray-rollover .solution {
    width: 140px;
    text-transform: uppercase;
    border-top: 1px solid #fff;
    text-align: center;
    margin-right: auto;
    margin-left: auto;
    padding-top: 10px;
    margin-top: 30px

}

.gray-rollover p,.gray-rollover div {
    color: #0c213d;
    text-align: center
}

.gray-rollover .rollover {
    padding: 20px;
    position: absolute;
    top: 0;
    right: 0;
    left: 0;
    bottom: 0;
    background: #003168;
    text-align: center;
    z-index: 10;
    transition: border-radius 350ms ease;
    transform: translate(0, 100%);
    height: 100%;
    transition: transform .5s ease
}

.gray-rollover .rollover * {
    color: #fff
}

.gray-rollover .fa-chevron-down {
    margin-right: auto;
    margin-left: auto;
    left: 45%;
    position: absolute;
    bottom: 20px
}

.gray-rollover:hover .rollover,
.gray-rollover.is-open .rollover {
    display: block;
    transition: border-radius 350ms ease;
    display: flex;
    justify-content: center;
    align-content: center;
    flex-direction: column;
    padding-top: 0px;
    transform: translate(0, 0);
    transition: transform .5s ease;
    transition-timing-function: cubic-bezier(0, 1, 0.5, 1)
}

