/* =========================================
   RBC CM - Featured Conferences
   All rules scoped to .rbccm-featured-conferences
   Mobile-first; desktop overrides at min-width: 992px
   ========================================= */

.rbccm-featured-conferences {
  /* Mobile-first: plain dark-blue fill, no watermark. The wave/dot background
     image is layered on at the desktop breakpoint (see media query below). */
  background-color: #002144;
  color: #FFFDFD;
  padding: 0;
}

.rbccm-featured-conferences__container {
  margin: 0 auto;
  max-width: 1140px;
  padding: 35px 16px 45px;
}

.rbccm-featured-conferences__heading {
  color: #FFFDFD;
  font-family: "RBCDisplay", Georgia, Times, serif !important;
  font-size: 24px;
  font-weight: 500;
  margin: 0 0 24px 0;
  padding: 0;
}

/* -- Outer tabs (conference selector) - mobile: stacked, 100% wide -- */
.rbccm-featured-conferences__tablist {
  align-items: center;
  align-self: stretch;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin: 0 0 28px 0;
}

.rbccm-featured-conferences__tab {
  align-items: center;
  align-self: stretch;
  background: var(--Blue-Dark-Blue, #003168);
  border: 1.5px solid var(--Neutral-White, #FFF);
  border-radius: 10px;
  color: #FFFDFD;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  font-family: Roboto, Arial, Verdana, sans-serif;
  font-size: 16px;
  font-style: normal;
  font-weight: 700;
  gap: 12px;
  justify-content: center;
  line-height: 120%;
  padding: 19px 0;
  text-align: center;
  transition: background-color 0.2s ease, color 0.2s ease;
  width: 100%;
}

.rbccm-featured-conferences__tab:hover {
  background-color: rgba(255, 255, 255, 0.08);
}

.rbccm-featured-conferences__tab.is-active {
  background-color: #FFFDFD;
  color: var(--Blue-Dark-Blue, #003168);
}

/* -- Outer panels (one per conference) -- */
.rbccm-featured-conferences__panel {
  display: none;
}

.rbccm-featured-conferences__panel.is-active {
  display: block;
}

/* -- Inner accordion (mobile) -- */
.rbccm-featured-conferences__inner-wrap {
  border-top: 1px solid rgba(255, 199, 54, 0.5);
}

.rbccm-featured-conferences__inner-tab {
  align-items: center;
  background: transparent;
  border: none;
  border-bottom: 1px solid rgba(255, 199, 54, 0.5);
  color: #FFFDFD;
  cursor: pointer;
  display: flex;
  font-family: "Roboto Medium", "Roboto", Arial, sans-serif;
  font-size: 18px;
  font-weight: 500;
  justify-content: space-between;
  padding: 18px 4px;
  text-align: left;
  width: 100%;
}

.rbccm-featured-conferences__inner-chevron {
  flex-shrink: 0;
  transform: rotate(180deg); /* closed = pointing down */
  transition: transform 0.25s ease;
}

.rbccm-featured-conferences__inner-tab.is-active .rbccm-featured-conferences__inner-chevron {
  transform: rotate(0deg); /* open = pointing up */
}

.rbccm-featured-conferences__inner-panel {
  display: none;
  padding: 24px 0;
}

/* Adjacent sibling reveal on mobile */
.rbccm-featured-conferences__inner-tab.is-active + .rbccm-featured-conferences__inner-panel {
  border-bottom: 1px solid rgba(255, 199, 54, 0.5);
  display: block;
}

/* -- Overview panel -- */
.rbccm-featured-conferences__overview {
  align-items: flex-start;
  align-self: stretch;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.rbccm-featured-conferences__video {
  aspect-ratio: 16 / 9; /* locks the 16:9 box natively; the padding-top trick
                            on __video-frame below still works as belt-and-
                            suspenders for very old browsers */
  background: #000;
  max-width: 1140px;
  position: relative;
  width: 100%;
}

/* 16:9 aspect-ratio frame - padding-top trick keeps it responsive without aspect-ratio
   (matches the working production embed pattern). */
.rbccm-featured-conferences__video-frame {
  display: block;
  height: 0;
  overflow: hidden;     /* clip the poster/iframe to the 16:9 box */
  padding-top: 56.25%; /* 9 / 16 */
  position: relative;
  width: 100%;
}

.rbccm-featured-conferences__video-frame iframe {
  border: 0;
  height: 100%;
  left: 0;
  position: absolute;
  top: 0;
  width: 100%;
}

/* Click-to-play facade (rendered when a custom Poster Override is set).
   The Brightcove iframe is injected over this on click. */
.rbccm-featured-conferences__video-facade {
  background: #000;
  border: 0;
  cursor: pointer;
  display: block;
  height: 100%;
  left: 0;
  margin: 0;
  padding: 0;
  position: absolute;
  top: 0;
  width: 100%;
}

.rbccm-featured-conferences__video-facade:focus-visible {
  outline: 3px solid #0051a5;
  outline-offset: 2px;
}

.rbccm-featured-conferences__video-poster {
  display: block;
  height: 100%;
  left: 0;
  object-fit: cover;
  position: absolute;
  top: 0;
  width: 100%;
}

.rbccm-featured-conferences__video-play {
  align-items: center;
  background: rgba(0, 49, 104, 0.85);
  border-radius: 50%;
  color: #fff;
  display: flex;
  height: 72px;
  justify-content: center;
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  transition: background-color 0.2s ease, transform 0.2s ease;
  width: 72px;
}

.rbccm-featured-conferences__video-facade:hover .rbccm-featured-conferences__video-play,
.rbccm-featured-conferences__video-facade:focus-visible .rbccm-featured-conferences__video-play {
  background: #003168;
  transform: translate(-50%, -50%) scale(1.06);
}

.rbccm-featured-conferences__video-play-icon {
