  font-size: 14px;
  margin: 32px 0 0 0;
  padding-top: 24px;
  text-align: center;
}

/* -- Speakers slider (fully manual transform-based carousel) --
   The slider clips overflow. The `.__speakers` row is a flex container with
   194px cards and 32px gaps (5 cards = 5x194 + 4x32 = 1098px). JS translates
   the row left/right by exactly one card-step (194 + 32 = 226px) per arrow
   click. Dots jump directly to a specific card index.

   No scroll-snap, no slick, no measurement step at init. Pure CSS layout +
   JS-managed transform = predictable behavior at every viewport, including
   the first reveal of a previously-hidden accordion panel. */
.rbccm-featured-conferences__speakers-slider {
  align-self: stretch;
  display: flex;
  flex-direction: column;
  gap: 24px;
  margin: 24px 0;
  overflow: hidden;                /* clip the row when it translates out of view */
  position: relative;
  width: 100%;
}

.rbccm-featured-conferences__speakers {
  display: flex;
  flex-wrap: nowrap;
  gap: 32px;
  margin: 0;
  padding: 0;
  transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
  will-change: transform;
}

.rbccm-featured-conferences__speakers > .rbccm-featured-conferences__speaker {
  flex: 0 0 194px;
  width: 194px;
}

/* Slider controls (arrows + dots) - visible whenever the speakers row
   overflows the slider's viewport (i.e. navigation IS needed). JS adds a
   `.has-overflow` class to the slider when that's the case and removes it
   when all speakers fit. Without that class, the controls hide.

   This makes the visibility count + viewport-aware: on desktop with <=5
   speakers, the row fits (1098px) inside the inner-panel so the controls
   hide; with 6+ speakers it overflows, controls show. On mobile the row
   essentially always overflows, so controls always show. */
.rbccm-featured-conferences__speakers-controls {
  align-items: center;
  display: flex;
  gap: 16px;
  justify-content: center;
  margin: 0;
  padding: 5px 0;
}
.rbccm-featured-conferences__speakers-slider:not(.has-overflow) .rbccm-featured-conferences__speakers-controls {
  display: none;
}

.rbccm-featured-conferences__speakers-btn {
  align-items: center;
  background: transparent;
  border: 0;
  color: #FFFDFD;
  cursor: pointer;
  display: flex;
  height: 24px;
  justify-content: center;
  padding: 0;
  transition: opacity 0.2s ease;
  width: 24px;
}
.rbccm-featured-conferences__speakers-btn:disabled,
.rbccm-featured-conferences__speakers-btn[aria-disabled="true"] {
  cursor: default;
  opacity: 0.3;
  pointer-events: none;
}

/* Dots - generated in JS as plain `<button class="__speakers-dot">` elements
   (one per REAL speaker, not the clones). */
.rbccm-featured-conferences__speakers-dots {
  align-items: center;
  display: flex;
  gap: 26px;
  margin: 0;
  padding: 0;
}
.rbccm-featured-conferences__speakers-dot {
  background: transparent;
  border: 1px solid #FFFDFD;
  border-radius: 50%;
  cursor: pointer;
  height: 10px;
  padding: 0;
  text-indent: -9999px;
  width: 10px;
}

/* CSS source-order note: the dot focus rules MUST come before .is-active so
   that .is-active wins by source order when both apply (e.g. user just
   clicked a dot - it has both :focus and .is-active). Same specificity
   (0,0,2,0), so later-declared rule wins. */
.rbccm-featured-conferences__speakers-dot:focus { outline: none; }
.rbccm-featured-conferences__speakers-dot:focus-visible {
  outline: 1px solid #FFC72C;
  outline-offset: 4px;
}
.rbccm-featured-conferences__speakers-dot.is-active {
  background: #FFFDFD;
  border-radius: 50px;
  outline: 1px solid #FFC72C;
  outline-offset: 4px;
}

/* -- Insights panel --
   Simple responsive grid: 1 col mobile / 2 col tablet / 3 col desktop,
   24px gap throughout. No carousel — cards just flow.
   The featured card spans every column at every breakpoint and uses
   row-reverse on tablet+ to put the image on the right of the body. */

/* Slider wrapper is now just a flex column container — no overflow clip
   (we're not translating anything), no transitions. Kept the class name
   to avoid markup changes. */
.rbccm-featured-conferences__insights-slider {
  align-self: stretch;
  display: flex;
  flex-direction: column;
  gap: 24px;
  margin: 0;
  position: relative;
  width: 100%;
}

/* Cards grid. The intermediate __insights-row wrapper is transparent via
   display: contents so the cards participate directly in this grid.

   The `transform: none !important` defeats any inline transform the legacy
   carousel JS still applies on init (it tries to translate the track to
   pin "card 0" to the slider's left edge — meaningless in a grid layout
   and would push every card off-screen). */
.rbccm-featured-conferences__insights {
  display: grid;
  grid-template-columns: 1fr;             /* mobile: single column */
  gap: 24px;
  margin: 0;
  padding: 0;
  transform: none !important;
  transition: none !important;
}

/* Cloned cards inserted by the legacy carousel JS — hide at every
   breakpoint so the grid only shows the real cards. */
.rbccm-featured-conferences__insight[data-clone] {
  display: none !important;
}

@media (min-width: 768px) {
  .rbccm-featured-conferences__insights {
    grid-template-columns: repeat(2, 1fr); /* tablet */
  }
}
@media (min-width: 992px) {
  .rbccm-featured-conferences__insights {
    grid-template-columns: repeat(3, 1fr); /* desktop */
  }
}

.rbccm-featured-conferences__insights-row {
  display: contents;
}

/* -- Individual insight card -- */
.rbccm-featured-conferences__insight {
  align-items: flex-start;
  background: #FFFDFD;
  color: #000;
  display: flex;
  flex-direction: column;
  text-decoration: none;
  width: 100%;
}
.rbccm-featured-conferences__insight:hover,
.rbccm-featured-conferences__insight:focus-visible {
  color: #000;
  text-decoration: none;
}

/* Card image - 240px tall, full card width. Hover scales 1.08; the wrapper
   clips overflow so the layout doesn't shift. */
.rbccm-featured-conferences__insight-media {
  align-self: stretch;
  flex-shrink: 0;
  height: 240px;
  overflow: hidden;
}
.rbccm-featured-conferences__insight-media img {
  display: block;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
  width: 100%;
}

/* Card body - contains label / divider / title / desc / meta.
   Spacing between each element is handled by per-element margin-top
   (label -> divider: 11px, divider -> title: 16px, title -> desc: 16px,
   desc -> meta: auto so meta pins to the bottom of the body). */
.rbccm-featured-conferences__insight-body {
  align-items: flex-start;
  align-self: stretch;
  display: flex;
  flex: 1;
  flex-direction: column;
  padding: 20px;
}



/* -- Hover effects --
   Match the upcoming-conferences card pattern: divider widens from 30.9 ->
   56px, image scales to 1.08. `@media (hover: hover)` gates this to devices
   with a hover-capable input (skip touch-only where hover doesn't make sense).
   `:focus-visible` mirrors the effect for keyboard users. */
@media (hover: hover) {
  .rbccm-featured-conferences__insight:hover,
  .rbccm-featured-conferences__insight:focus-visible {
    outline: none;
  }
  .rbccm-featured-conferences__insight:hover .rbccm-featured-conferences__insight-media img,
  .rbccm-featured-conferences__insight:focus-visible .rbccm-featured-conferences__insight-media img {
    transform: scale(1.08);
  }
  .rbccm-featured-conferences__insight:hover .rbccm-featured-conferences__insight-divider,
