/* =========================================
   Font-family lockdown.
   External stylesheets (unified.css / unified2.css) include broad selectors
   like `*` and bare `h3` that apply font-family DIRECTLY to descendants of
   our component, beating any inherited !important from a parent class.
   The block below pins typography per-element with !important so those
   universal/element selectors can't slip through.

   Hierarchy:
   1) Default - every element inside the component is Roboto Light.
   2) Headings (h2 / h3) - RBCDisplay.
   3) Medium-weight bits (strong, themes-label, active tabs, buttons).
   ========================================= */

/* 1) Default body type for every descendant */
.rbccm-featured-conferences,
.rbccm-featured-conferences * {
  font-family: "Roboto Light", "Roboto", Arial, sans-serif !important;
}

/* 2) Headings */
.rbccm-featured-conferences h2,
.rbccm-featured-conferences h3,
.rbccm-featured-conferences .rbccm-featured-conferences__heading,
.rbccm-featured-conferences .rbccm-featured-conferences__overview-heading,
.rbccm-featured-conferences .rbccm-featured-conferences__speakers-heading {
  font-family: "RBCDisplay", Georgia, Times, serif !important;
}

/* 3) Medium-weight elements.
   .__inner-tab is Medium by default (mobile accordion). On desktop, only the
   active inner-tab is Medium - the inactive one drops to Light (see rule
   below in the desktop media query). Each selector also targets `* `
   descendants so the universal `.rbccm-featured-conferences *` Light rule
   above (specificity 0,0,1,0) can't reach the inner-tab label `<span>`. */
.rbccm-featured-conferences strong,
.rbccm-featured-conferences .rbccm-featured-conferences__themes-label,
.rbccm-featured-conferences .rbccm-featured-conferences__tab.is-active,
.rbccm-featured-conferences .rbccm-featured-conferences__tab.is-active *,
.rbccm-featured-conferences .rbccm-featured-conferences__inner-tab,
.rbccm-featured-conferences .rbccm-featured-conferences__inner-tab *,
.rbccm-featured-conferences .rbccm-featured-conferences__inner-tab.is-active,
.rbccm-featured-conferences .rbccm-featured-conferences__inner-tab.is-active * {
  font-family: "Roboto Medium", "Roboto", Arial, sans-serif !important;
}

/* Desktop: inactive inner-tab (and its label span) drops back to Light */
@media (min-width: 992px) {
  .rbccm-featured-conferences .rbccm-featured-conferences__inner-tab:not(.is-active),
  .rbccm-featured-conferences .rbccm-featured-conferences__inner-tab:not(.is-active) * {
    font-family: "Roboto Light", "Roboto", Arial, sans-serif !important;
  }
}

/* ============================================================
   Insight card typography — matches the live RBCCM .story-card
   .tile--news .tile--gib pattern exactly. Values pulled from the
   live computed styles so the cards visually align with the rest
   of the site (homepage tiles, GIB insights, etc.).
   ============================================================ */

/* INSIGHTS eyebrow label */
.rbccm-featured-conferences__insight-label {
  color: #006AC3 !important;
  font-size: 14px;
  font-weight: 400;
  letter-spacing: 2px;
  line-height: 140%;
  margin: 0 0 5px 0;
  text-transform: uppercase;
}

/* Yellow divider line — short stub under the eyebrow label.
   Width animates to 56px on hover (handled by the hover rule above). */
.rbccm-featured-conferences__insight-divider {
  background: #FFC72C;
  flex-shrink: 0;
  height: 2px;
  margin: 0;
  transition: width 0.3s ease;
  width: 30.9px;
}

/* Card title — bold black, 15px below the divider. */
.rbccm-featured-conferences__insight-title {
  color: #000;
  font-weight: 700;
  font-size: 20px;
  line-height: 25px;
  margin: 15px 0 10px 0;
}

/* Card description — gray body copy, no top margin (sits tight under
   the title), 20px breathing room below. */
.rbccm-featured-conferences__insight-desc {
  color: #555;
  font-size: 14px;
  font-weight: 400;
  line-height: 140%;
  margin: 0 0 20px 0;
}

/* "X min read / watch / listen" + chevron arrow — pinned to the
   bottom of the body via margin-top: auto. Same blue + hover-underline
   as the live "learn-more" link pattern.

   `display: inline-flex` + `width: fit-content` shrinks the meta to
   wrap its content, so the hover border-bottom only runs the length of
   the text + arrow rather than the full card width. `border-bottom`
   beats `text-decoration: underline` here because text-decoration
   stops at the SVG arrow boundary; a border extends underneath both. */
.rbccm-featured-conferences__insight-meta {
  align-items: center;
  border-bottom: 1px solid transparent;
  color: #006AC3;
  display: inline-flex;
  font-size: 14px;
  font-weight: 600;
  gap: 7px;
  line-height: 20px;
  margin: auto 0 0 0;
  padding-bottom: 2px;
  transition: border-color 0.2s ease;
  width: fit-content;
}
.rbccm-featured-conferences__insight:hover .rbccm-featured-conferences__insight-meta,
.rbccm-featured-conferences__insight:focus-visible .rbccm-featured-conferences__insight-meta {
  border-bottom-color: currentColor;
}


/* =========================================================================
   TABBED-AREA GRID — companion to the main component above.
   -------------------------------------------------------------------------
   Block: .rbccm-featured-conferences-tabbed
   Emitted by featured-conferences-homepage.html (sibling XSL). Renders as
   a simple 3-up grid inside a tabbed content area (e.g. on the homepage),
   pulling from the same Events List DCR, filtered by
   sitelocation = rbccm-homepage. Light-blue panel, dark text — visually
   distinct from the dark-blue main featured-conferences component above.

   Mobile-first: 1 column. Tablet/desktop (≥768px): 3 columns.
   No carousel, no tabs of its own, no JS — pure static grid.
   ========================================================================= */

/* ---------- Block / section ---------- */
.rbccm-featured-conferences-tabbed {
  background: #EFF6FD;
  padding: 40px 16px;
}

.rbccm-featured-conferences-tabbed__inner {
  margin: 0 auto;
  max-width: 1100px;
  text-align: center;
}


/* ---------- Heading + icon ---------- */
.rbccm-featured-conferences-tabbed__heading {
  align-items: center;
  color: var(--Blue-Dark-Blue, #003168);
  display: inline-flex;
  font-family: "RBCDisplay", Georgia, Times, serif;
  font-size: 24px;
  font-weight: 500;
  gap: 12px;
  justify-content: center;
  letter-spacing: -0.789px;
  line-height: normal;
  margin: 0 0 32px 0;
}

.rbccm-featured-conferences-tabbed__icon {
  color: var(--Blue-Dark-Blue, #003168);
  flex-shrink: 0;
  height: 32px;
  width: 32px;
}


/* ---------- List / grid ---------- */
.rbccm-featured-conferences-tabbed__list {
  display: grid;
  gap: 30px;
  grid-template-columns: 1fr;
  list-style: none;
  margin: 0;
  padding: 0;
}

@media (min-width: 768px) {
  .rbccm-featured-conferences-tabbed__list {
    grid-template-columns: repeat(3, 1fr);
  }
}


/* ---------- Item / event ---------- */
.rbccm-featured-conferences-tabbed__item {
  align-items: center;
  display: flex;
  flex-direction: column;
  padding: 0 12px;
  text-align: center;
}


/* ---------- Date circle ----------
   98×98 white round on the light-blue panel. Flex-centered so the
   month + day stack vertically with no padding hacks needed. */
.rbccm-featured-conferences-tabbed__date {
  align-items: center;
  background: #FFFFFF;
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  height: 98px;
  justify-content: center;
  margin: 0 auto 20px;
  width: 98px;
}

.rbccm-featured-conferences-tabbed__date-month {
  color: var(--Blue-Dark-Blue, #003168);
  font-family: Roboto, Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 1px;
  line-height: normal;
  text-transform: uppercase;
}

.rbccm-featured-conferences-tabbed__date-day {
  color: var(--Blue-Dark-Blue, #003168);
  font-family: "RBCDisplay", Georgia, Times, serif;
  font-size: 28px;
  font-weight: 700;
  line-height: normal;
  margin-top: 2px;
}


/* ---------- Location ---------- */
.rbccm-featured-conferences-tabbed__location {
  color: #353535;
  font-family: Roboto, Arial, sans-serif;
  font-size: 14px;
  font-weight: 400;
  letter-spacing: 1.5px;
  line-height: normal;
  margin: 0 0 8px 0;
  text-transform: uppercase;
}


/* ---------- Event name ---------- */
.rbccm-featured-conferences-tabbed__name {
  color: var(--Blue-Dark-Blue, #003168);
  font-family: "RBCDisplay", Georgia, Times, serif;
  font-size: 20px;
  font-weight: 500;
  line-height: 26px;
  margin: 0;
}

/* ---------- Desktop padding bump ---------- */
@media (min-width: 992px) {
  .rbccm-featured-conferences-tabbed {
    padding: 56px 16px;
  }

  .rbccm-featured-conferences-tabbed__heading {
    font-size: 32px;
    margin-bottom: 40px;
  }
}


/* ---------- Typography lockdown (same approach as the main component) ----------
   External site stylesheets use broad selectors like `*` and bare `p` that
   would otherwise override our font-family. Scoping !important rules to the
   homepage block keeps universal selectors from leaking in. */
.rbccm-featured-conferences-tabbed,
.rbccm-featured-conferences-tabbed * {
  font-family: Roboto, Arial, sans-serif !important;
}

/* RBCDisplay for heading, date day, and event name. */
.rbccm-featured-conferences-tabbed h2,
.rbccm-featured-conferences-tabbed .rbccm-featured-conferences-tabbed__heading,
.rbccm-featured-conferences-tabbed .rbccm-featured-conferences-tabbed__date-day,
.rbccm-featured-conferences-tabbed .rbccm-featured-conferences-tabbed__name,
.rbccm-featured-conferences-tabbed .rbccm-featured-conferences-tabbed__name * {
  font-family: "RBCDisplay", Georgia, Times, serif !important;
}

