/* ------------------------------------------------------------------
   Themes Section - Mobile First (Accordion)
   ------------------------------------------------------------------ */
.rbccm-themes {
  background-color: #002144;
  color: #FFFDFD;
  padding: 0;
}

.rbccm-themes__container {
  margin: 0 auto;
  max-width: 1140px;
}

.rbccm-themes__heading {
  color: #FFFDFD;
  font-family: "RBCDisplay", Georgia, Times, serif;
  font-size: 24px;
  font-weight: 500;
  margin: 0 !important;
  padding: 35px 16px;
}

/* Tab list for all viewports */
.rbccm-themes__tablist {
  border-top: 1px solid #FFFDFD;
  display: flex;
  flex-direction: column;
}

/* Individual tab button */
.rbccm-themes__tab {
  background: transparent;
  border: none;
  border-bottom: 1px solid #FFFDFD;
  color: #FFFDFD;
  cursor: pointer;
  font-family: "Roboto",Arial,Verdana,sans-serif;
  font-size: 18px;
  font-weight: 400;
  padding: 18px 48px 18px 40px;
  position: relative;
  text-align: left;
  width: 100%;
}

/* Chevron for mobile */
.rbccm-themes__chevron {
  height: 25px;
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%) rotate(180deg);
  transition: transform 0.3s ease;
  width: 24px;
}

/* Active tab on mobile */
.rbccm-themes__tab.is-active {
  /* font-weight: 700; */
}

.rbccm-themes__tab.is-active .rbccm-themes__chevron {
  transform: translateY(-50%) rotate(0deg);
}

/* Individual panel */
.rbccm-themes__panel {
  display: none;
  opacity: 0;
  padding: 24px 16px;
  transition: opacity 0.2s ease;
}

/* Show panel after active tab on mobile */
.rbccm-themes__tab.is-active + .rbccm-themes__panel {
  border-bottom: 1px solid white;
  display: block;
  opacity: 1;
}

.rbccm-theme__title {
  color: #FFFDFD;
  font-family: "RBCDisplay", Georgia, Times, serif;
  font-size: 20px;
  font-weight: 500;
  line-height: 1.2;
  margin: 0 0 16px 0;
}

.rbccm-theme__content {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.rbccm-theme__image {
  border-radius: 20px;
  height: auto;
  margin: 15px 0;
  width: 100%;
}

.rbccm-theme__text p {
  font-family: "Roboto Light", "Roboto", Arial, Verdana, sans-serif;
}

.rbccm-theme__text p,
.rbccm-themes__panel p {
  color: #FFFDFD;
  font-size: 16px;
  line-height: 1.6;
  margin: 0 0 12px 0;
}

.rbccm-themes__panel p {
  font-family: "Roboto Light", "Roboto", Arial, Verdana, sans-serif;
}

.rbccm-theme__text p:last-child {
  margin-bottom: 0;
}

