}

/* =============================================================
   Desktop overrides — min-width: 992px
   ============================================================= */
@media (min-width: 992px) {
  .rbccm-stats__header {
    padding: 35px 24px;
  }

  .rbccm-stats__title {
    font-size: 32px;
    line-height: normal;
  }

  .rbccm-stats__grid {
    padding: 40px 0 30px 0;
  }

  .rbccm-stats__item {
    padding: 0 70px;
  }

  .rbccm-stats__item--big {
    gap: 0;
  }

  .rbccm-stats__footnote {
    padding: 12px 0 26px;
  }
}

/* =========================================
   RBC CM -- Upcoming Conference Programming
   Scoped to .rbccm-upcoming-conferences
   Mobile-first; desktop at min-width: 992px
   ========================================= */

.rbccm-upcoming-conferences {
  align-items: center;
  align-self: stretch;
  background-color: #082043;
  color: #FFFDFD;
  display: flex;
  flex-direction: column;
  padding: 40px 16px;
  width: 100%;
}

.rbccm-upcoming-conferences__container {
  align-items: stretch;
  display: flex;
  flex-direction: column;
  gap: 40px;
  margin: 0 auto;
  max-width: 1132px;
  padding: 0;
  width: 100%;
}

.rbccm-upcoming-conferences__heading {
  color: var(--Neutral-White, #FFF);
  font-family: "RBCDisplay", "RBC Display", Georgia, Times, serif;
  font-size: 24px;
  font-style: normal;
  font-weight: 500;
  line-height: 120%; /* 28.8px */
  margin: 0;
}

.rbccm-upcoming-conferences__intro {
  color: var(--Neutral-White, #FFF);
  font-family: Roboto, Arial, sans-serif;
  font-size: 16px;
  font-style: normal;
  font-weight: 400;
  line-height: normal;
  margin: 0;
  max-width: 100%;
}

/* Keep heading + intro visually grouped (tight) while everything below stays at 40px */
.rbccm-upcoming-conferences__heading + .rbccm-upcoming-conferences__intro {
  margin-top: -28px;
}

/* -- Filters / search -- */
/* Visible by default: month + region dropdowns + free-text title search.
   JS (upcoming-conferences.js) builds the dropdown option lists from the
   data-month/data-region attributes on rendered cards. */
.rbccm-upcoming-conferences__filters {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.rbccm-upcoming-conferences__filter-group {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.rbccm-upcoming-conferences__filter-label {
  color: #FFFDFD;
  font-family: "Roboto", Arial, sans-serif;
  font-size: 14px;
}

.rbccm-upcoming-conferences__select-wrap {
  position: relative;
  flex: 1 1 0;
  min-width: 0;
}

.rbccm-upcoming-conferences__select {
  appearance: none;
  -webkit-appearance: none;
  background-color: transparent;
  border: 1px solid #FFFFFF;
  border-radius: 4px;
  color: #FFFDFD;
  font-family: "Roboto", Arial, sans-serif;
  font-size: 14px;
  padding: 10px 32px 10px 12px;
  width: 100%;
}

.rbccm-upcoming-conferences__select option {
  background-color: #002144;
  color: #FFFDFD;
}

.rbccm-upcoming-conferences__select-chevron {
  color: #FFFDFD;
  pointer-events: none;
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
}

.rbccm-upcoming-conferences__search {
  align-items: center;
  background-color: transparent;
  border: 1px solid #FFFFFF;
  border-radius: 4px;
  display: flex;
  gap: 8px;
  margin-bottom: 0;           /* it is a <label>; site Bootstrap adds a bottom margin */
  padding: 10px 12px;
  width: 100%;
}

/* Clear filters -- matches .rbccm-filter__reset (filter-by.css, Conference
   Insights): white outline + text on the navy section, yellow fill on
   hover/focus (the --dark hover colours). */
.rbccm-upcoming-conferences__reset {
  background: transparent;
  border: 1px solid #FFFFFF;
  border-radius: 5px;
  box-sizing: border-box;
  color: #FFFFFF;
  cursor: pointer;
  font-family: RBCDisplay, Georgia, Times, serif !important;
  font-size: 16px;
  font-style: normal;
  font-weight: 400;
  line-height: normal;
  padding: 14.5px 20px 9.5px 20px;
  transition: background 0.15s ease, color 0.15s ease;
  white-space: nowrap;
}
.rbccm-upcoming-conferences__reset:hover,
.rbccm-upcoming-conferences__reset:focus-visible {
  background: #FFC72C;
  border-color: #FFC72C;
  color: #002144;
  outline: none;
}

.rbccm-upcoming-conferences__search-icon {
  color: #FFFDFD;
  flex-shrink: 0;
}

.rbccm-upcoming-conferences__search-input {
  background: transparent;
  border: 0;
  color: #FFFFFF;
  flex: 1;
  font-family: "Roboto", Arial, sans-serif;
  font-size: 14px;
  outline: none;
  padding: 0;
}
.rbccm-upcoming-conferences__search-input::placeholder {
  color: rgba(255, 255, 255, 0.6);
}

/* SR-only utility */
.rbccm-upcoming-conferences__sr-only {
  border: 0;
  clip: rect(0 0 0 0);
  height: 1px;
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
  white-space: nowrap;
  width: 1px;
}

/* -- Cards container --
   Renders ALL upcoming conferences in the current year. CSS hides cards
   beyond index 6 by default so the visible grid stays at 6. When the user
   starts searching or selects a Month/Region filter, JS adds `.is-filtered`
   to this container, which lifts the default-6 cap and lets every matching
   card show. Non-matching cards get `.is-filtered-out` (display: none).
   On mobile the slick carousel takes over (`.is-carousel` mode). */
.rbccm-upcoming-conferences__cards {
  display: block;          /* slick will replace this on mobile */
  margin: 0;
}

/* Default state: hide cards beyond index 6.
   Scoped via :not(.is-carousel) so slick on mobile sees every slide. */
.rbccm-upcoming-conferences:not(.is-carousel) .rbccm-upcoming-conferences__cards:not(.is-filtered) .rbccm-upcoming-conferences__card:nth-of-type(n+7) {
  display: none;
}

/* When a filter / search is active: hide non-matching cards explicitly.
   `.is-filtered-out` is added by JS and beats the default-6 cap.
   `!important` is required to beat:
     1. The desktop override at .rbccm-upcoming-conferences:not(.is-carousel)
        .rbccm-upcoming-conferences__card { display: block; } (specificity 0,3,0)
     2. The mobile carousel rule .rbccm-upcoming-conferences.is-carousel
        .rbccm-upcoming-conferences__card { display: flex !important; }
   Filtered-out cards should NEVER show in any viewport. */
.rbccm-upcoming-conferences__card.is-filtered-out {
  display: none !important;
}

/* Empty state -- shown by JS when no cards match the active filter / search.
   Stacks an icon circle + heading + 2 messages + "Clear filters" button,
   centered both axes inside a 594px-tall container with 32px gap throughout. */
.rbccm-upcoming-conferences__empty {
  align-items: center;
  align-self: stretch;
  display: flex;
  flex-direction: column;
  gap: 32px;
  height: 594px;
  justify-content: center;
}

/* When the hidden attribute is present, the browser's UA stylesheet sets
   display: none, but our .__empty { display: flex } rule (specificity 0,1,0)
   would beat the [hidden] attribute selector (specificity 0,0,1). This rule
   restores hidden by raising specificity (0,1,1) to win over the flex rule. */
.rbccm-upcoming-conferences__empty[hidden] {
  display: none;
}

/* Mobile through tablet (0 up to and including iPad at 1024px): size the empty
   state to its content instead of the fixed 594px frame, and pull it up by 40px
   to cancel the parent .__container's `gap: 40px` so the no-results state does
   not leave a tall vertical void. Only true desktop (>1024px) keeps the full
   594px frame. */
@media (max-width: 1024px) {
  .rbccm-upcoming-conferences__empty {
    height: auto;
    margin-top: -40px;
  }
}

/* Circular icon wrapper (80x80) with thin blue outline + low-opacity blue fill.
   Asymmetric padding (19 top/right, 18 bottom/left) lifts the icon visually. */
.rbccm-upcoming-conferences__empty-icon-wrap {
  align-items: center;
  aspect-ratio: 1 / 1;
  background: rgba(45, 106, 168, 0.20);
  border: 1px solid #1D86F0;
  border-radius: 100px;
  display: flex;
  flex-shrink: 0;
  height: 80px;
  justify-content: center;
  padding: 19px 19px 18px 18px;
  width: 80px;
}

.rbccm-upcoming-conferences__empty-icon {
  aspect-ratio: 1 / 1;
  flex-shrink: 0;
  height: 43px;
  width: 43px;
}

.rbccm-upcoming-conferences__empty-heading {
  color: var(--Neutral-White, #FFF);
  font-family: "RBCDisplay", "RBC Display", Georgia, Times, serif;
  font-size: 30px;
  font-style: normal;
  font-weight: 500;
  line-height: normal;
  margin: 0;
  text-align: center;
}

/* The two messages share the same base styling; the second one (--emphasis) is
   set to weight 500 to read as a softer call-to-action. */
.rbccm-upcoming-conferences__empty-message {
  color: var(--Neutral-White, #FFF);
  font-family: "RBCDisplay", "RBC Display", Georgia, Times, serif;
  font-size: 18px;
  font-style: normal;
  font-weight: 400;
  line-height: 120%;
  margin: 0;
  text-align: center;
}

.rbccm-upcoming-conferences__empty-message--emphasis {
  font-weight: 500;
  line-height: normal;
}

/* "Clear filters" reset button. Matches the section CTA styling
   (212 x 50, 10px radius, white outline, Inter 16/500) but lives inside
   the empty state and triggers the JS reset (see upcoming-conferences.js). */
.rbccm-upcoming-conferences__empty-clear {
  align-items: center;
  background: transparent;
  border: 1px solid #FFF;
  border-radius: 10px;
  color: #FFF;
  cursor: pointer;
  display: flex;
  flex-shrink: 0;
  font-family: Inter, "Roboto Medium", "Roboto", Arial, sans-serif;
  font-size: 16px;
  font-style: normal;
  font-weight: 500;
  height: 50px;
  justify-content: center;
  line-height: 24px;
  padding: 0 61px 0 62px;
  text-align: center;
  width: 212px;
}

.rbccm-upcoming-conferences__empty-clear:hover {
  background-color: rgba(255, 255, 255, 0.08);
}

/* -- Card -- */
.rbccm-upcoming-conferences__card {
  aspect-ratio: 1 / 1;
  background-color: #003168;
  color: #FFFDFD;
  display: block;
  margin: 0 auto;
  max-width: 360px;
  overflow: hidden;
  position: relative;
  text-decoration: none;
  width: 100%;
}

/* Slick overrides -- same pattern as leadership-slider (proven on production).
   Cards have fixed pixel width via !important so variableWidth can measure them. */
#rbccm-upcoming-conferences.is-carousel .slick-track {
  display: flex !important;
  align-items: stretch !important;
}
#rbccm-upcoming-conferences.is-carousel .slick-slide {
  box-sizing: border-box;
  float: none;
  height: auto;
  margin: 0 !important;
}
#rbccm-upcoming-conferences.is-carousel .slick-slide > div,
#rbccm-upcoming-conferences.is-carousel .slick-slide > div > div {
  height: 100%;
}
#rbccm-upcoming-conferences.is-carousel .slick-list {
  overflow: visible;          /* lets neighbor cards "peek" out of the list */
}
#rbccm-upcoming-conferences.is-carousel .slick-prev,
#rbccm-upcoming-conferences.is-carousel .slick-next {
  display: none !important;
}

/* Card on mobile -- Figma: 343px wide, flex column, gap 10px, align-items flex-start */
.rbccm-upcoming-conferences.is-carousel .rbccm-upcoming-conferences__card {
  align-items: flex-start;
  display: flex !important;
  flex-direction: column;
  gap: 10px;
  margin: 0 8px;
  max-width: none;
  width: 343px !important;
}

/* The .__cards wrapper clips the peek so the section never overflows horizontally,
   and beats slick-theme's default `.slick-dotted.slick-slider { margin-bottom: 30px }`. */
.rbccm-upcoming-conferences.is-carousel .rbccm-upcoming-conferences__cards {
  margin-bottom: 0 !important;
  overflow: hidden;
}
.rbccm-upcoming-conferences__card:hover,
.rbccm-upcoming-conferences__card:focus-visible {
  color: #FFFDFD;
  text-decoration: none;
}

/* Cards without an href are inert (no pointer, no focus, no scroll-jump) */
.rbccm-upcoming-conferences__card:not([href]) {
  cursor: default;
}

.rbccm-upcoming-conferences__card-media {
  inset: 0;
  position: absolute;
  z-index: 0;
}
.rbccm-upcoming-conferences__card-media::after {
  background-color: rgba(0, 49, 104, 0.8); /* #003168 @ 80% -- overlay for contrast */
  content: "";
  inset: 0;
  pointer-events: none;
  position: absolute;
  z-index: 1; /* ensure overlay sits above the img */
}
.rbccm-upcoming-conferences__card-media img {
  display: block;
  height: 100%;
  object-fit: cover;
  width: 100%;
}

.rbccm-upcoming-conferences__card-date {
  align-items: flex-start;
  display: flex;
  flex-direction: column;
  gap: 4px;
  left: 24px;
  position: absolute;
  top: 24px;
  z-index: 1;
}

.rbccm-upcoming-conferences__card-month {
  color: #FFF;
  font-family: Roboto, Arial, sans-serif;
  font-size: 12px;
  font-style: normal;
  font-weight: 500;
  letter-spacing: 1.2px;
  line-height: 16px;
  margin: 0;
  text-transform: uppercase;
}

.rbccm-upcoming-conferences__card-day {
  color: #FFF;
  font-family: Roboto, Arial, sans-serif;
  font-size: 36px;
  font-style: normal;
  font-weight: 300;
  letter-spacing: -1.8px;
  line-height: 40px;
  margin: 0;
}

.rbccm-upcoming-conferences__card-body {
  align-items: flex-start;
  bottom: 24px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  left: 24px;
  position: absolute;
  right: 24px;
  z-index: 1;
}

.rbccm-upcoming-conferences__card-divider {
  background-color: #FFF;
  display: block;
  height: 2px;
  margin: 0;
  width: 32px;
}

.rbccm-upcoming-conferences__card-title {
  color: #FFF;
  font-family: "RBCDisplay", "RBC Display", Georgia, Times, serif;
  font-size: 20px;
  font-style: normal;
  font-weight: 500;
  line-height: 27.5px;
  margin: 0;
}

.rbccm-upcoming-conferences__card-location {
  align-items: center;
  color: #FFF;
  display: flex;
  font-family: Roboto, Arial, sans-serif;
  font-size: 14px;
  font-style: normal;
  font-weight: 400;
  gap: 8px;
  line-height: 20px;
  margin: 0;
}

.rbccm-upcoming-conferences__pin {
  color: #FFF;
  flex-shrink: 0;
  height: 16px;
  width: 16px;
}

/* -- Mobile carousel controls -- */
/* Arrows | dots | arrow. With many conferences the dots WRAP onto extra rows
   between the arrows instead of pushing them out of bounds (same pattern as
   deal-carousel). align-items: center keeps the arrows level with the middle
   of however many dot rows there are. */
.rbccm-upcoming-conferences__controls {
  align-items: center;
  display: none;
  gap: 16px;
  justify-content: center;
  margin: 0;
  max-width: 100%;
}

.rbccm-upcoming-conferences.is-carousel .rbccm-upcoming-conferences__controls {
  display: flex;
}

.rbccm-upcoming-conferences__btn {
  align-items: center;
  background: transparent;
  border: 0;
  color: #FFFDFD;
  cursor: pointer;
  display: flex;
  height: 24px;
  justify-content: center;
  padding: 0;
  transition: opacity 0.2s ease;
  width: 24px;
  flex: 0 0 auto;               /* arrows never shrink; the dots give way */
}
.rbccm-upcoming-conferences__btn:disabled,
.rbccm-upcoming-conferences__btn[aria-disabled="true"] {
  cursor: default;
}

/* Dots */
/* flex: 0 1 auto + min-width: 0 let the dots box shrink below its content
   width, which is what forces the wrap (a flex item will not shrink past its
   content without min-width: 0). */
.rbccm-upcoming-conferences__dots {
  flex: 0 1 auto;
  min-width: 0;
}
.rbccm-upcoming-conferences__dots .slick-dots {
  align-items: center;
  bottom: auto;
  display: flex !important;
  flex-wrap: wrap;
  gap: 16px 26px;               /* 16px between wrapped rows, 26px between dots */
  justify-content: center;
  list-style: none;
  margin: 0;
  padding: 0;
  position: static;
  width: auto;
}

.rbccm-upcoming-conferences__dots .slick-dots li {
  height: 10px;
  margin: 0;
  padding: 0;
  width: 10px;
}

.rbccm-upcoming-conferences__dots .slick-dots li button {
  background: transparent;
  border: 1px solid #FFFDFD;
  border-radius: 50%;
  cursor: pointer;
  height: 10px;
  padding: 0;
  text-indent: -9999px;
  width: 10px;
}
.rbccm-upcoming-conferences__dots .slick-dots li button:before {
  display: none;
}
.rbccm-upcoming-conferences__dots .slick-dots li.slick-active button {
  background: #FFFDFD;
  border-radius: 50px;
  /* 1px yellow ring sitting 4px outside the dot -- true outline, no fill */
  outline: 1px solid var(--Yellow-Warm-Yellow, #FFC72C);
  outline-offset: 4px;
}

/* Keep the active ring visible on focus AND show the same ring when tabbing through
   inactive dots, so keyboard users can see where focus lands. */
.rbccm-upcoming-conferences__dots .slick-dots li button:focus,
.rbccm-upcoming-conferences__dots .slick-dots li button:focus-visible {
  outline: 1px solid var(--Yellow-Warm-Yellow, #FFC72C);
  outline-offset: 4px;
}

/* -- CTA -- */
.rbccm-upcoming-conferences__cta-wrap {
  display: flex;
  justify-content: center;
  margin-top: 0;
}

.rbccm-upcoming-conferences__cta {
  align-items: center;
  background-color: transparent;
  border: 1px solid #FFFDFD;
  border-radius: 4px;
  color: #FFF !important;
  display: inline-flex;
  font-family: Inter, "Roboto Medium", "Roboto", Arial, sans-serif;
  font-size: 16px;
  font-style: normal;
  font-weight: 500;
  height: 50px;
  justify-content: center;
  line-height: 24px;
  padding: 0 27px;
  text-align: center;
  text-decoration: none;
}
.rbccm-upcoming-conferences__cta:hover {
  background-color: rgba(255, 255, 255, 0.08);
  color: #FFFDFD;
  text-decoration: none;
}

/* ---------------------------------------------
   DESKTOP (min-width: 992px)
   --------------------------------------------- */
@media (min-width: 992px) {

  .rbccm-upcoming-conferences {
    padding: 64px 0;
  }

  .rbccm-upcoming-conferences__container {
    gap: 43px;
    padding: 0;
  }

  .rbccm-upcoming-conferences__heading {
    font-size: 32px;
  }

  .rbccm-upcoming-conferences__intro {
    font-size: 18px;
  }

  /* Filter row: label + selects on the left, search on the right */
  .rbccm-upcoming-conferences__filters {
    align-items: center;
    flex-direction: row;
    flex-wrap: wrap;
    gap: 16px;
    justify-content: space-between;
    margin-bottom: 0px;
  }
  .rbccm-upcoming-conferences__filter-group {
    flex: 0 0 auto;
    gap: 10px;
  }
  .rbccm-upcoming-conferences__select-wrap {
    flex: 0 0 auto;
    width: 140px;
    margin: 0;
  }
  .rbccm-upcoming-conferences__search {
    flex: 0 0 auto;
    margin-left: auto;          /* search + Clear filters sit together on the right */
    width: 320px;
  }
  .rbccm-upcoming-conferences__reset {
    flex: 0 0 auto;
  }

  /* Card grid -- 3 cols, 24px gap, total inner width = 1100px */
  .rbccm-upcoming-conferences__cards {
    display: grid;
    gap: 24px;
    grid-template-columns: repeat(3, 1fr);
    overflow: visible;          /* clears the is-carousel overflow: hidden */
  }

  /* Desktop cards (when carousel is NOT active) -- beat any residual inline styles. */
  .rbccm-upcoming-conferences:not(.is-carousel) .rbccm-upcoming-conferences__card {
    aspect-ratio: auto;
    display: block;
    height: 400px;
    margin: 0;
    max-width: none;
    width: auto;
  }

  /* Desktop hover -- image zooms inside the fixed card frame; divider grows; overlay + content stay put */
  @media (hover: hover) {
    .rbccm-upcoming-conferences__card:hover,
    .rbccm-upcoming-conferences__card:focus-visible {
      outline: none;
    }
    .rbccm-upcoming-conferences__card:hover .rbccm-upcoming-conferences__card-media img,
    .rbccm-upcoming-conferences__card:focus-visible .rbccm-upcoming-conferences__card-media img {
      transform: scale(1.08);
    }
    .rbccm-upcoming-conferences__card:hover .rbccm-upcoming-conferences__card-divider,
    .rbccm-upcoming-conferences__card:focus-visible .rbccm-upcoming-conferences__card-divider {
      width: 56px;
    }
  }

  /* Smooth zoom on the image + grow on the divider */
  .rbccm-upcoming-conferences__card-media img {
    transition: transform 0.4s ease;
  }
  .rbccm-upcoming-conferences__card-divider {
    transition: width 0.3s ease;
  }

  /* Mobile carousel controls are never used on desktop */
  .rbccm-upcoming-conferences__controls,
  .rbccm-upcoming-conferences.is-carousel .rbccm-upcoming-conferences__controls {
    display: none;
  }
}

/* =========================================
   Conference Listing Modal
   Lives inside Bootstrap's .modal pattern.
   BEM-scoped overrides + flex layout (no tables).
   ========================================= */

/* Dialog + content frame.
   !important needed to beat Bootstrap's .modal-dialog { width: auto; margin: 10px } */
.rbccm-upcoming-conferences__modal-dialog {
  /* !important beats Bootstrap's `.modal-dialog { margin: 10px }` (modals.less)
     and the wider-viewport `.modal-dialog { margin: 30px auto }`, both of
     which load after this file and win by source order at equal specificity.
     `auto` left/right centers the dialog horizontally on viewports wider than
     the 960px max-width; 20px at the bottom leaves breathing room before the
     viewport bottom. */
  margin: 0 auto 20px auto !important;
  max-width: 960px;
  padding: 20px;
  top: 0;
  width: 100% !important;
}

.rbccm-upcoming-conferences__modal-content {
  margin: 0 auto;
  max-width: 900px;
  width: 100%;
}

.rbccm-upcoming-conferences__modal-header {
  border: none;
  border-top: 8px solid #FBDE00;
  padding: 0;
}

.rbccm-upcoming-conferences__modal-close {
  color: #595959;
  font-size: 41px;
  font-weight: normal;
}

.rbccm-upcoming-conferences__modal-body {
  /* !important beats Bootstrap's `.modal-body { padding: 15px }` (modals.less)
     which loads after this file and wins at equal specificity (0,1,0). */
  padding: 0 !important;
}

/* Heading block (h2 + subtitle) */
.rbccm-upcoming-conferences__modal-intro {
  align-items: center;
  display: flex;
  justify-content: space-between;
  min-height: 141px;
  padding: 0 32px;
}

.rbccm-upcoming-conferences__modal-titles {
  align-items: flex-start;
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  gap: 4px;
  max-width: 455px;
}

.rbccm-upcoming-conferences__modal-heading {
  color: #003168;
  font-family: Inter, "Roboto Medium", "Roboto", Arial, sans-serif;
  font-size: 32px;
  font-style: normal;
  font-weight: 500;
  line-height: 48px;
  margin: 0;
}

.rbccm-upcoming-conferences__modal-subtitle {
  color: #2C2C2C;
  font-family: Inter, "Roboto", Arial, sans-serif;
  font-size: 16px;
  font-style: normal;
  font-weight: 400;
  line-height: 24px;
  margin: 0;
}

/* Conference list */
.rbccm-upcoming-conferences__modal-list {
  align-items: flex-start;
  display: flex;
  flex: 1 0 0;
  flex-direction: column;
  padding: 0 47px 32px 32px;
}

.rbccm-upcoming-conferences__modal-list-inner {
  align-items: flex-start;
  align-self: stretch;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

/* Each row */
.rbccm-upcoming-conferences__modal-row {
  align-items: center;
  align-self: stretch;
  border-bottom: 1px solid #F3F4F6;
  display: flex;
  flex-shrink: 0;
  gap: 24px;
  height: 57px;
  padding: 0 16px;
}

/* Date column */
.rbccm-upcoming-conferences__modal-date {
  color: #003168;
  flex-shrink: 0;
  font-family: Inter, "Roboto Medium", "Roboto", Arial, sans-serif;
  font-size: 16px;
  font-style: normal;
  font-weight: 500;
  line-height: 24px;
  min-width: 90px;          /* keeps dates aligned across rows */
}

/* Title (middle column) */
.rbccm-upcoming-conferences__modal-title {
  color: #003168;
  flex: 1;
  font-family: Inter, "Roboto Medium", "Roboto", Arial, sans-serif;
  font-size: 16px;
  font-style: normal;
  font-weight: 500;
  line-height: 24px;
  margin: 0;
}

/* Location (icon + text) */
.rbccm-upcoming-conferences__modal-location {
  align-items: center;
  color: #2C2C2C;
  display: flex;
  flex-shrink: 0;
  gap: 8px;
  height: 20px;
}

.rbccm-upcoming-conferences__modal-location svg {
  flex-shrink: 0;
}

.rbccm-upcoming-conferences__modal-location-text {
  color: #2C2C2C;
  font-family: Inter, "Roboto", Arial, sans-serif;
  font-size: 14px;
  font-style: normal;
  font-weight: 400;
  line-height: 20px;
  white-space: nowrap;
}

/* -- Mobile -- */
@media (max-width: 767.98px) {
  .rbccm-upcoming-conferences__modal-intro {
    min-height: auto;
    padding: 24px 16px 0;
  }
  .rbccm-upcoming-conferences__modal-heading {
    font-size: 22px;
    line-height: 32px;
  }
  .rbccm-upcoming-conferences__modal-list {
    padding: 8px;
  }
  .rbccm-upcoming-conferences__modal-row {
    flex-wrap: wrap;
    gap: 4px 16px;
    height: auto;
    min-height: 57px;
    padding: 12px 8px;
  }
  .rbccm-upcoming-conferences__modal-date {
    min-width: 0;
  }
  .rbccm-upcoming-conferences__modal-title {
    flex-basis: 100%;
  }
}

