https://www.rbcis.com/assets/rbcits/css/:
:root {
	--blue: #005DAA;
	--blue-dark: #003366;
	--yellow: #FFD200;
	--yellow-dim: #7A6000;
	--text: #1A1A1A;
	--muted: #6B7280;
	--border: #E2E6EC;
	--page: #FFFFFF;
	--card: #FFFFFF;
	--teal: #005DAA;
	--sans: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, sans-serif;
}

.rbcis-awards__skip-link {
	position: absolute;
	left: -999px;
	top: auto;
	width: 1px;
	height: 1px;
	overflow: hidden;
}

.rbcis-awards__skip-link:focus {
	position: fixed;
	top: 0;
	left: 0;
	width: auto;
	height: auto;
	padding: .5rem 1rem;
	background: var(--yellow);
	color: var(--blue-dark);
	font-weight: 700;
	z-index: 9999;
	font-size: .9rem;
}

*,
*::before,
*::after {
	box-sizing: border-box;
	margin: 0;
	padding: 0;
}

html {
	scroll-behavior: smooth;
}

body {
	font-family: var(--sans);
	background: var(--page);
	color: var(--text);
	font-size: 16px;
	line-height: 1.6;
}

/* NAV */
.rbcis-awards__site-nav {
	background: var(--card);
	border-bottom: 3px solid var(--blue);
	position: sticky;
	top: 0;
	z-index: 100;
	padding: 0 2rem;
}

.rbcis-awards__nav-inner {
	max-width: 72rem;
	margin: 0 auto;
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 60px;
}

.rbcis-awards__logo-text {
	font-size: .95rem;
	font-weight: 800;
	color: var(--blue);
	text-decoration: none;
}

.rbcis-awards__nav-cta {
	background: var(--blue);
	color: #fff;
	font-size: .85rem;
	font-weight: 700;
	padding: .45rem 1.1rem;
	border-radius: 6px;
	text-decoration: none;
	transition: background .15s;
}

.rbcis-awards__nav-cta:hover {
	background: var(--blue-dark);
}



/* CATEGORY NAV */
.rbcis-awards__cat-nav {
	max-width: 72rem;
	margin: 0 auto;
	padding: 1.25rem 2rem .75rem;
	display: flex;
	flex-wrap: wrap;
	gap: .5rem;
}


a.rbcis-awards__cat-nav-link {
	text-decoration: none;
}

.rbcis-awards__cat-nav-link {
	font-size: .8rem;
	font-weight: 700;
	color: var(--muted);
	background: var(--card);
	border: 1px solid var(--border);
	border-radius: 20px;
	padding: .28rem .85rem;
	text-decoration: none;
	transition: all .15s;
}

.rbcis-awards__cat-nav-link:hover {
	background: #E8F1FB;
	color: var(--blue);
	border-color: #B8D4F0;
}

.rbcis-awards__cat-nav-link.rbcis-awards__nav-2025 {
	color: var(--blue);
	border-color: var(--blue);
	background: #EBF3FF;
}

.rbcis-awards__cat-nav-link.rbcis-awards__nav-2025:hover {
	background: var(--blue);
	color: #fff;
}

/* DIVIDER between 2025 and older sections */
.rbcis-awards__section-divider {
	max-width: 72rem;
	margin: 1.5rem auto 0;
	padding: 0 2rem;
}

.rbcis-awards__section-divider-label {
	font-size: .75rem;
	font-weight: 700;
	color: var(--muted);
	text-transform: uppercase;
	letter-spacing: .08em;
	display: flex;
	align-items: center;
	gap: .75rem;
	margin-bottom: .25rem;
}

.rbcis-awards__section-divider-label::after {
	content: "";
	flex: 1;
	height: 1px;
	background: var(--border);
}

/* CATEGORY SECTION */
.rbcis-awards__cat-section {
	max-width: 72rem;
	margin: 0 auto;
	padding: 1.5rem 2rem .75rem;
}

.rbcis-awards__cat-heading {
	font-size: 1.35rem;
	font-weight: 800;
	color: var(--blue-dark);
	letter-spacing: -.015em;
	margin-bottom: 1rem;
	display: flex;
	align-items: center;
	gap: .6rem;
}

.rbcis-awards__cat-badge-2025 {
	font-size: .65rem;
	font-weight: 800;
	background: var(--yellow);
	color: var(--yellow-dim);
	padding: .15rem .55rem;
	border-radius: 100px;
	text-transform: uppercase;
	letter-spacing: .07em;
}

/* AWARD CARD */
.rbcis-awards__container {
	display: grid;
	grid-template-columns: 1fr;
	gap: .85rem;
	align-items: start;
}

.rbcis-awards__card {
	background: var(--card);
	border: 1px solid var(--border);
	border-radius: 10px;
	padding: 1.5rem 1.6rem;
	display: flex;
	align-items: flex-start;
	gap: 1.5rem;
	transition: box-shadow .18s;
	box-shadow: 0 1px 4px rgba(0, 0, 0, .06);
}

.rbcis-awards__card:hover {
	box-shadow: 0 6px 22px rgba(0, 60, 140, .12);
}

.rbcis-awards__content {
	flex: 1;
	min-width: 0;
}

.rbcis-awards__title {
	font-size: 1.05rem;
	font-weight: 700;
	color: var(--blue);
	line-height: 1.3;
	margin-bottom: .3rem;
}

.rbcis-awards__region {
	font-size: .8rem;
	color: var(--muted);
	margin-bottom: .65rem;
}

.rbcis-awards__rule {
	width: 2.25rem;
	height: 3px;
	background: var(--yellow);
	border-radius: 2px;
	margin-bottom: .7rem;
}

.rbcis-awards__pub {
	font-size: .88rem;
	font-weight: 700;
	color: var(--text);
	margin-bottom: .4rem;
}

.rbcis-awards__desc {
	font-size: .86rem;
	color: var(--muted);
	line-height: 1.65;
	margin-bottom: .6rem;
}

.rbcis-awards__year-badge {
	display: inline-flex;
	align-items: center;
	font-size: .68rem;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: .07em;
	padding: .18rem .6rem;
	border-radius: 100px;
}

.rbcis-awards__badge-2025 {
	background: var(--yellow);
	color: var(--yellow-dim);
}

.rbcis-awards__badge-old {
	background: #EAECEF;
	color: var(--muted);
}

/* LOGO BOX */
.rbcis-awards__logo-box {
	flex-shrink: 0;
	width: 160px;
	height: 120px;
	background: transparent;
	border: none;
	border-radius: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: .5rem;
	overflow: hidden;
}


/* Collapsible for older awards */
.rbcis-awards__collapsible-wrapper {
	margin-top: 1rem;
}

.rbcis-awards__collapsible-toggle {
	width: auto;
	background: transparent;
	border: none;
	border-radius: 0;
	padding: .4rem 0;
	font-size: 1.36rem;
	font-weight: 600;
	color: var(--blue);
	cursor: pointer;
	display: inline-flex;
	align-items: center;
	gap: .35rem;
	transition: color .15s;
	text-align: left;
}

.rbcis-awards__collapsible-toggle:hover {
	background: transparent;
	color: var(--blue-dark);
	text-decoration: underline;
}

.rbcis-awards__collapsible-toggle::after {
	content: '\25BC';
	font-size: .65rem;
	color: var(--blue);
	transition: transform .2s;
}

.rbcis-awards__collapsible-toggle[aria-expanded="true"]::after {
	transform: rotate(180deg);
}

.rbcis-awards__collapsible-content {
	max-height: 0;
	overflow: hidden;
	transition: max-height .3s ease-out;
}

.rbcis-awards__collapsible-content.rbcis-awards__open {
	max-height: 5000px;
	transition: max-height .5s ease-in;
}

.rbcis-awards__collapsible-content .rbcis-awards__card {
	margin-top: 1.5rem;
}

.rbcis-awards__pub-logo-img {
	max-width: 100%;
	max-height: 100%;
	width: auto;
	height: auto;
	object-fit: contain;
	display: block;
}

.rbcis-awards__pub-logo-text {
	font-size: .6rem;
	font-weight: 700;
	color: var(--muted);
	text-align: center;
	line-height: 1.35;
}

/* FOOTER */
.rbcis-awards__site-footer {
	background: var(--blue-dark);
	color: rgba(255, 255, 255, .55);
	padding: 1.5rem 2rem;
	font-size: .8rem;
	margin-top: 2.5rem;
}

.rbcis-awards__footer-inner {
	max-width: 72rem;
	margin: 0 auto;
	display: flex;
	justify-content: space-between;
	align-items: center;
	flex-wrap: wrap;
	gap: .5rem;
}

.rbcis-awards__footer-links {
	display: flex;
	gap: 1.5rem;
}

.rbcis-awards__footer-inner a {
	color: rgba(255, 255, 255, .5);
	text-decoration: none;
}

.rbcis-awards__footer-inner a:hover {
	color: var(--yellow);
}

@media (max-width: 640px) {
	.rbcis-awards__container {
		grid-template-columns: 1fr;
	}

	.rbcis-awards__card {
		flex-direction: column;
	}

	.rbcis-awards__hero-inner {
		flex-direction: column;
	}

	.rbcis-awards__cat-section,
	.rbcis-awards__cat-nav,
	.rbcis-awards__section-divider {
		padding-left: 1.25rem;
		padding-right: 1.25rem;
	}
}

@media print {

	.rbcis-awards__site-nav,
	.rbcis-awards__site-footer,
	.rbcis-awards__cat-nav {
		display: none;
	}

	.rbcis-awards__card {
		break-inside: avoid;
		box-shadow: none;
		border: 1px solid #ccc;
	}
}

/* FEATURED AWARDS CAROUSEL */
.rbcis-awards__sr-only {
	position: absolute;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	border: 0;
}

/* Page header - clean section like RBC Wealth Management with refined hierarchy */
.rbcis-awards__page-header {
	background: #F2F4F7;
