.rbcis-stats-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}

/* ── Individual stat cell ── */
.rbcis-stat-item {
  flex: 1 1 0;
  text-align: center;
  padding: 10px 20px;
