/*===================================================================================*/
/* AWARDS PAGE 2026 - 06
/*===================================================================================*/
:root {
	--blue: #005DAA;
	--blue-dark: #003366;
	--yellow: #FFD200;
	--yellow-dim: #7A6000;
	--text: #1A1A1A;
	--muted: #6B7280;
	--border: #E2E6EC;
	--page: #EBF3FB;
	--card: #FFFFFF;
	--teal: #005DAA;
	--sans: "Segoe UI", -apple-system, BlinkMacSystemFont, Roboto, sans-serif;
}

/*body {
  background: var(--page) !important;
}*/

.rbcits-skip-link {
	position: absolute;
	left: -999px;
	top: auto;
	width: 1px;
	height: 1px;
	overflow: hidden;
}

.rbcits-skip-link:focus {
	position: fixed;
	top: 0;
	left: 0;
	width: auto;
	height: auto;
	padding: .5rem 1rem;
	background: var(--yellow);
	color: var(--blue-dark);
	font-weight: 700;
	z-index: 9999;
	font-size: .9rem;
}

/* NAV */
.rbcits-site-nav {
	background: var(--card);
	border-bottom: 3px solid var(--blue);
	position: sticky;
	top: 0;
	z-index: 100;
	padding: 0 2rem;
}

.rbcits-nav-inner {
	max-width: 72rem;
	margin: 0 auto;
	display: flex;
	align-items: center;
	justify-content: space-between;
	height: 60px;
}

.rbcits-logo-text {
	font-size: .95rem;
	font-weight: 800;
	color: var(--blue);
	text-decoration: none;
}

.rbcits-nav-cta {
	background: var(--blue);
	color: #fff;
	font-size: .85rem;
	font-weight: 700;
	padding: .45rem 1.1rem;
	border-radius: 6px;
	text-decoration: none;
	transition: background .15s;
}

.rbcits-nav-cta:hover {
	background: var(--blue-dark);
}

/* HERO BANNER */
.rbcits-hero-banner {
	background: #FFFFFF;
	overflow: hidden;
}

.rbcits-hero-inner {
	max-width: 115rem;
	margin: 11rem auto auto;
	display: flex;
	align-items: stretch;
	min-height: 380px;
}

.rbcits-hero-left {
	flex: 0 0 60%;
	display: flex;
	flex-direction: column;
	justify-content: center;
	padding: 3.5rem 0 0;
	background: #FFFFFF;
}

.rbcits-hero-left h1 {
	font-size: clamp(2rem, 4vw, 5rem);
	font-weight: 800;
	letter-spacing: -.03em;
	color: var(--blue-dark);
	line-height: 1.15;
	margin-bottom: 1.2rem;
}

.rbcits-hero-intro {
	font-size: 1.4rem;
	color: #374151;
	line-height: 1.8;
	max-width: 520px;
	margin-bottom: 0;
}

.rbcits-hero-cta-bar {
	display: flex;
	align-items: center;
	margin-top: 2.5rem;
}

.rbcits-hero-cta {
	display: inline-flex;
	align-items: center;
	gap: .65rem;
	background: #c8c5b7;
	color: #000 !important;
	font-size: 1.5rem;
	font-weight: 700;
	padding: 1.7rem 2.7rem;
	text-decoration: none;
	letter-spacing: .01em;
	transition: background .15s;
	min-width: 340px;
}

.rbcits-hero-cta:hover {
	background: var(--blue-dark);
}

.rbcits-hero-cta-arrow {
	font-size: 1.1rem;
}

.rbcits-hero-right {
	flex: 0 0 40%;
	overflow: hidden;
}

.rbcits-hero-right img {
	width: 100%;
	height: 100%;
	object-fit: cover;
	object-position: center top;
	display: block;
}

/* CATEGORY NAV */
.rbcits-cat-nav {
	max-width: 113rem;
	margin: 0 auto;
	padding: 1.25rem 2rem .75rem;
	display: flex;
	flex-wrap: wrap;
	gap: .5rem;
}

.rbcits-cat-nav-link {
	font-size: 1.3rem;
	font-weight: 700;
	color: var(--muted);
	background: var(--card);
	border: 1px solid var(--border);
	border-radius: 20px;
	padding: .30rem .90rem;
	text-decoration: none;
	transition: all .15s;
}

.rbcits-cat-nav-link:hover {
	background: #E8F1FB;
	color: var(--blue);
	border-color: #B8D4F0;
}

.rbcits-cat-nav-link.rbcits-nav-2025 {
	color: var(--blue);
	border-color: var(--blue);
	background: #EBF3FF;
}

.rbcits-cat-nav-link.rbcits-nav-2025:hover {
	background: var(--blue);
	color: #fff;
}

/* DIVIDER between 2025 and older sections */
.rbcits-section-divider {
	max-width: 72rem;
	margin: 1.5rem auto 0;
	padding: 0 2rem;
}

.rbcits-section-divider-label {
	font-size: .75rem;
	font-weight: 700;
	color: var(--muted);
	text-transform: uppercase;
	letter-spacing: .08em;
	display: flex;
	align-items: center;
	gap: .75rem;
	margin-bottom: .25rem;
}

.rbcits-section-divider-label::after {
	content: "";
	flex: 1;
	height: 1px;
	background: var(--border);
}

/* CATEGORY SECTION */
.rbcits-cat-section {
	max-width: 113rem;
	margin: 0 auto;
	padding: 1.5rem 2rem .75rem;
}

.rbcits-cat-heading {
	font-size: 2rem;
	font-weight: 800;
	color: var(--blue-dark);
	letter-spacing: -.015em;
	margin-bottom: 1rem;
	display: flex;
	align-items: center;
	gap: .6rem;
}

.rbcits-cat-badge-2025 {
	font-size: .65rem;
	font-weight: 800;
	background: var(--yellow);
	color: var(--yellow-dim);
	padding: .15rem .55rem;
	border-radius: 100px;
	text-transform: uppercase;
	letter-spacing: .07em;
}

/* AWARD CARD */
.rbcits-awards-container {
	display: grid;
	grid-template-columns: 1fr;
	gap: .85rem;
	align-items: start;
}

.rbcits-award-card {
	background: var(--card);
	border: 1px solid var(--border);
	border-radius: 10px;
	padding: 1.5rem 1.6rem;
	display: flex;
	align-items: flex-start;
	gap: 1.5rem;
	transition: box-shadow .18s;
	box-shadow: 0 1px 4px rgba(0, 0, 0, .06);
}

.rbcits-award-card:hover {
	box-shadow: 0 6px 22px rgba(0, 60, 140, .12);
}

.rbcits-award-content {
	flex: 1;
	min-width: 0;
}

.rbcits-award-title {
	font-size: 1.6rem;
	font-weight: 700;
	color: var(--blue);
	line-height: 1.3;
	margin-bottom: .3rem;
}

.rbcits-award-region {
	font-size: 1.1rem;
	color: var(--muted);
	margin-bottom: .65rem;
}

.rbcits-award-rule {
	width: 2.25rem;
	height: 3px;
	background: var(--yellow);
	border-radius: 2px;
	margin-bottom: .7rem;
}

.rbcits-award-pub {
	font-size: 1.4rem;
	font-weight: 700;
	color: var(--text);
	margin-bottom: .4rem;
}

.rbcits-award-desc {
	font-size: 1.2rem;
	color: var(--muted);
	line-height: 1.7;
	margin-bottom: .6rem;
}

.rbcits-year-badge {
	display: inline-flex;
	align-items: center;
	font-size: .9rem;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: .07em;
	padding: .18rem .6rem;
	border-radius: 100px;
}

.rbcits-badge-2025 {
	background: var(--yellow);
	color: var(--yellow-dim);
}

.rbcits-badge-old {
	background: #EAECEF;
	color: var(--muted);
}

/* LOGO BOX */
.rbcits-award-logo-box {
	flex-shrink: 0;
	width: 108px;
	height: 108px;
	background: transparent;
	border: none;
	border-radius: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: .85rem;
	overflow: hidden;
}

.rbcits-pub-logo-img {
	max-width: 100%;
	max-height: 100%;
	width: auto;
	height: auto;
	object-fit: contain;
}

