  font-weight: 300;
  font-size: 2.3rem;
}

.rbcis-contact-hero-rule {
  width: 50px;
  height: 3px;
  background: #fedf01;
  margin-bottom: 20px;
}

.rbcis-contact-hero h1 {
  font-size: clamp(28px, 4vw, 50px);
  font-weight: 400;
  color: #003168;
  line-height: 1.15;
  margin-bottom: 20px;
}

.rbcis-contact-hero-sub {
  font-size: 20px;
  color: #444;
  line-height: 1.65;
  max-width: fit-content;
}

.rbcis-contact-hero-image {
  flex: 1 1 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 260px;
}

.rbcis-contact-hero-image-note {
